import {
	pgTable,
	text,
	integer,

	timestamp,
	date,
	jsonb,
	uuid,
	index,
	uniqueIndex,
} from 'drizzle-orm/pg-core';
import { relations } from 'drizzle-orm';

/**
 * Gift-card system tables. The auth tables live in ./auth-schema.ts
 * (generated by the Better Auth CLI) and are re-exported at the bottom so
 * drizzle-kit sees one schema.
 *
 * Money is integer cents. Dates that are "a day" (due, valid until) are DATE;
 * moments are TIMESTAMPTZ.
 */

/** One row per year; `last` is the last number handed out. */
export const numberSequences = pgTable('number_sequences', {
	year: integer('year').primaryKey(),
	last: integer('last').notNull().default(0),
});

/**
 * Lifecycle, in order. A card and its invoice share one number
 * (YYYY-NNNN); the invoice is a separate row because it may one day be
 * re-issued or credited without touching the card.
 *
 *   draft         created, nothing sent yet (also where web requests land)
 *   invoice_sent  invoice emailed, waiting for the money
 *   paid          money confirmed by hand
 *   card_sent     gift card emailed
 *   redeemed      guests have been
 *   cancelled     from any state before redeemed
 */
export const CARD_STATUSES = [
	'draft',
	'invoice_sent',
	'paid',
	'card_sent',
	'redeemed',
	'cancelled',
] as const;
export type CardStatus = (typeof CARD_STATUSES)[number];

export const CARD_LANGUAGES = ['lv', 'en', 'ru'] as const;
export type CardLanguage = (typeof CARD_LANGUAGES)[number];

/** Photo on the right half of the card, by key; resolved to a file in lib/giftcards/photos.ts. */
export const CARD_PHOTOS = ['sauna', 'paintball', 'guesthouse', 'celebration', 'archery'] as const;
export type CardPhoto = (typeof CARD_PHOTOS)[number];

export const giftCards = pgTable(
	'gift_cards',
	{
		id: uuid('id').primaryKey().defaultRandom(),
		number: text('number').notNull(),
		year: integer('year').notNull(),
		seq: integer('seq').notNull(),
		status: text('status', { enum: CARD_STATUSES }).notNull().default('draft'),

		buyerName: text('buyer_name').notNull(),
		buyerEmail: text('buyer_email').notNull(),
		buyerPhone: text('buyer_phone'),

		/** The invoice line, e.g. "Peintbols un iekurināta pirts 3 stundu garumā, 8 personām". */
		serviceLine: text('service_line').notNull(),
		amountCents: integer('amount_cents').notNull(),
		currency: text('currency').notNull().default('EUR'),

		cardTitle: text('card_title').notNull(),
		cardSubtitle: text('card_subtitle'),
		cardNote: text('card_note'),
		cardPhoto: text('card_photo', { enum: CARD_PHOTOS }).notNull().default('sauna'),
		language: text('language', { enum: CARD_LANGUAGES }).notNull().default('lv'),

		validUntil: date('valid_until').notNull(),
		dueDate: date('due_date').notNull(),

		invoiceSentAt: timestamp('invoice_sent_at', { withTimezone: true }),
		paidAt: timestamp('paid_at', { withTimezone: true }),
		paidNote: text('paid_note'),
		cardSentAt: timestamp('card_sent_at', { withTimezone: true }),
		redeemedAt: timestamp('redeemed_at', { withTimezone: true }),
		cancelledAt: timestamp('cancelled_at', { withTimezone: true }),
		cancelReason: text('cancel_reason'),

		/** 'admin' when created in the dashboard, 'web' for the public request form. */
		source: text('source', { enum: ['admin', 'web'] }).notNull().default('admin'),
		createdBy: text('created_by'),
		createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
		updatedAt: timestamp('updated_at', { withTimezone: true }).notNull().defaultNow(),
	},
	table => [
		uniqueIndex('gift_cards_number_idx').on(table.number),
		index('gift_cards_status_idx').on(table.status),
		index('gift_cards_buyer_email_idx').on(table.buyerEmail),
	]
);

export const invoices = pgTable(
	'invoices',
	{
		id: uuid('id').primaryKey().defaultRandom(),
		number: text('number').notNull(),
		cardId: uuid('card_id')
			.notNull()
			.references(() => giftCards.id, { onDelete: 'cascade' }),
		issueDate: date('issue_date').notNull(),
		dueDate: date('due_date').notNull(),
		buyerName: text('buyer_name').notNull(),
		buyerEmail: text('buyer_email').notNull(),
		buyerPhone: text('buyer_phone'),
		lineDescription: text('line_description').notNull(),
		amountCents: integer('amount_cents').notNull(),
		currency: text('currency').notNull().default('EUR'),
		/** Set once the PDF is rendered and stored (Vercel Blob). */
		pdfUrl: text('pdf_url'),
		sentAt: timestamp('sent_at', { withTimezone: true }),
		createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
		updatedAt: timestamp('updated_at', { withTimezone: true }).notNull().defaultNow(),
	},
	table => [uniqueIndex('invoices_number_idx').on(table.number), index('invoices_card_idx').on(table.cardId)]
);

export const EVENT_TYPES = [
	'requested',
	'created',
	'updated',
	'invoice_sent',
	'invoice_opened',
	'marked_paid',
	'marked_unpaid',
	'card_sent',
	'redeemed',
	'cancelled',
	'note',
	'email_failed',
] as const;
export type EventType = (typeof EVENT_TYPES)[number];

export const events = pgTable(
	'events',
	{
		id: uuid('id').primaryKey().defaultRandom(),
		cardId: uuid('card_id')
			.notNull()
			.references(() => giftCards.id, { onDelete: 'cascade' }),
		type: text('type', { enum: EVENT_TYPES }).notNull(),
		/** Email of the admin, 'system', or 'web'. */
		actor: text('actor').notNull(),
		note: text('note'),
		meta: jsonb('meta').$type<Record<string, unknown>>(),
		createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
	},
	table => [index('events_card_idx').on(table.cardId, table.createdAt)]
);

export const giftCardRelations = relations(giftCards, ({ one, many }) => ({
	invoice: one(invoices, { fields: [giftCards.id], references: [invoices.cardId] }),
	events: many(events),
}));
export const invoiceRelations = relations(invoices, ({ one }) => ({
	card: one(giftCards, { fields: [invoices.cardId], references: [giftCards.id] }),
}));
export const eventRelations = relations(events, ({ one }) => ({
	card: one(giftCards, { fields: [events.cardId], references: [giftCards.id] }),
}));

export type GiftCard = typeof giftCards.$inferSelect;
export type NewGiftCard = typeof giftCards.$inferInsert;
export type Invoice = typeof invoices.$inferSelect;
export type CardEvent = typeof events.$inferSelect;

export * from './auth-schema';

